+    throw new Error(`invalid range: ${trimmed}`);
+  }
+  if (a < 1 || a > 65535 || b < 1 || b > 65535) {
+    throw new Error(`port out of range: ${trimmed}`);
+  }
+  if (b < a) {
+    throw new Error(`range end below start: ${trimmed}`);
